package cn.reviewsystem.recommend;

import java.math.BigDecimal;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
class RecommendationServiceTest {
 static final Instant NOW=Instant.parse("2026-11-20T12:00:00Z");
 @Autowired JdbcTemplate db;VersionedRecommendationConfig cfg=new VersionedRecommendationConfig();RecommendationService service;
 String prefix;long user,chapter;List<Long> questions=new ArrayList<>();List<Long> kps=new ArrayList<>();
 @BeforeEach void setup(){prefix="m06"+UUID.randomUUID().toString().replace("-","").substring(0,8);user=db.queryForObject("INSERT INTO rs_user(username,password_hash,role) VALUES (?,'x','STUDENT') RETURNING id",Long.class,prefix);chapter=db.queryForObject("INSERT INTO rs_chapter(subject_id,code,name,sort_order) VALUES (1,?,?,900) RETURNING id",Long.class,prefix.toUpperCase(),prefix);service=new RecommendationService(db,cfg,Clock.fixed(NOW,ZoneOffset.UTC));}
 @AfterEach void cleanup(){db.update("DELETE FROM rs_change_event WHERE source_id IN (SELECT id FROM rs_practice WHERE user_id=?)",user);db.update("DELETE FROM rs_practice_item WHERE practice_id IN (SELECT id FROM rs_practice WHERE user_id=?)",user);db.update("DELETE FROM rs_practice WHERE user_id=?",user);db.update("DELETE FROM rs_learning_activity WHERE user_id=?",user);db.update("DELETE FROM rs_mastery_current WHERE user_id=?",user);db.update("DELETE FROM rs_mastery_snapshot WHERE user_id=?",user);db.update("DELETE FROM rs_evidence WHERE user_id=?",user);for(long q:questions){db.update("UPDATE rs_question SET current_version_id=NULL WHERE id=?",q);db.update("DELETE FROM rs_question_version WHERE question_id=?",q);db.update("DELETE FROM rs_question WHERE id=?",q);}db.update("DELETE FROM rs_knowledge_point WHERE chapter_id=?",chapter);db.update("DELETE FROM rs_chapter WHERE id=?",chapter);db.update("DELETE FROM rs_user WHERE id=?",user);}

 @Test void fixedClockProducesIdenticalFieldsAndOrder(){long k=kp(1,true);for(int i=0;i<3;i++)question(k,"MANUAL","ACTIVE");snapshot(k,3,"60",NOW.minus(2,ChronoUnit.DAYS));var a=service.recommend(user,3);var b=service.recommend(user,3);assertEquals(a,b);}
 @Test void nTwoKnowledgeIsDiagnosticOnly(){long k=kp(1,true);question(k,"MANUAL","ACTIVE");snapshot(k,2,"30",NOW.minus(1,ChronoUnit.DAYS));var r=service.recommend(user,1);assertTrue(r.review().isEmpty());assertEquals(String.valueOf(k),r.diagnostic().getFirst().knowledgeId());}
 @Test void priorityFormulaIsExact0605(){long k=kp(1,true);List<Long> qs=new ArrayList<>();for(int i=0;i<5;i++)qs.add(question(k,"MANUAL","ACTIVE"));snapshot(k,3,"30",NOW.minusSeconds(302400));for(int i=0;i<5;i++)evidence(k,qs.get(i),i<2?"0":"1","CHOICE",NOW.minusSeconds(3600L*i));var f=service.recommend(user,1).review().getFirst().reason();same("0.7",f.weakness());same("0.5",f.time());same("0.4",f.error());same("0.6050",f.priority());assertEquals(2,f.errorNumerator());assertEquals(5,f.errorDenominator());}
 @Test void timeFactorCapsAtOneAfterSevenDays(){long k=kp(1,true);question(k,"MANUAL","ACTIVE");snapshot(k,3,"50",NOW.minus(8,ChronoUnit.DAYS));same("1",service.recommend(user,1).review().getFirst().reason().time());}
 @Test void nullSubjectiveResultIsExcludedFromErrorDenominator(){long k=kp(1,true);long q1=question(k,"MANUAL","ACTIVE"),q2=question(k,"MANUAL","ACTIVE");snapshot(k,3,"50",NOW.minus(2,ChronoUnit.DAYS));evidence(k,q1,null,"SHORT_ANSWER",NOW.minus(2,ChronoUnit.DAYS));evidence(k,q2,"0.5","SHORT_ANSWER",NOW.minus(3,ChronoUnit.DAYS));var f=service.recommend(user,1).review().getFirst().reason();assertEquals(1,f.errorNumerator());assertEquals(1,f.errorDenominator());}
 @Test void priorityTiesUseEarlierPracticeThenKnowledgeId(){long later=kp(1,true),early=kp(2,true),sameTimeHigher=kp(3,true);question(later,"MANUAL","ACTIVE");question(early,"MANUAL","ACTIVE");question(sameTimeHigher,"MANUAL","ACTIVE");snapshot(later,3,"100",NOW.minus(8,ChronoUnit.DAYS));snapshot(early,3,"100",NOW.minus(9,ChronoUnit.DAYS));snapshot(sameTimeHigher,3,"100",NOW.minus(9,ChronoUnit.DAYS));var ordered=service.recommend(user,3).plannedKnowledge().stream().filter(p->p.pool().equals("REVIEW")).toList();assertEquals(String.valueOf(early),ordered.get(0).knowledgeId());assertEquals(String.valueOf(sameTimeHigher),ordered.get(1).knowledgeId());}
 @Test void reviewShortageIsFilledByDiagnosticWithoutDuplicates(){long review=kp(1,true);for(int i=0;i<5;i++)question(review,"MANUAL","ACTIVE");snapshot(review,3,"40",NOW.minus(2,ChronoUnit.DAYS));for(int x=2;x<=6;x++){long k=kp(x,true);question(k,"MANUAL","ACTIVE");}var r=service.recommend(user,10);assertEquals(5,r.review().size());assertEquals(5,r.diagnostic().size());assertEquals(10,r.items().stream().map(RecommendationDtos.Item::questionId).distinct().count());}
 @Test void totalThreeReturnsThreeAndShortfallReason(){long k=kp(1,true);for(int i=0;i<3;i++)question(k,"MANUAL","ACTIVE");var r=service.recommend(user,10);assertEquals(3,r.items().size());assertEquals(7,r.shortfall().getFirst().missing());assertFalse(r.shortfall().getFirst().reason().isBlank());}
 @Test void cooldownExcludesThenExplicitlyRelaxes(){long k=kp(1,true),old=question(k,"MANUAL","ACTIVE"),recent=question(k,"MANUAL","ACTIVE");snapshot(k,3,"40",NOW.minus(12,ChronoUnit.HOURS));evidence(k,recent,"0","CHOICE",NOW.minus(12,ChronoUnit.HOURS));var one=service.recommend(user,1);assertEquals(String.valueOf(old),one.items().getFirst().questionId());var two=service.recommend(user,2);var relaxed=two.items().stream().filter(i->i.questionId().equals(String.valueOf(recent))).findFirst().orElseThrow();assertTrue(relaxed.reason().cooldownRelaxed());assertNotNull(relaxed.reason().cooldownReason());}
 @Test void suspendedAndDisabledAreExcludedAndOriginsHaveEqualTreatment(){long enabled=kp(1,true),disabled=kp(2,false);long manual=question(enabled,"MANUAL","ACTIVE"),ai=question(enabled,"AI_GENERATED","ACTIVE");question(enabled,"MANUAL","SUSPENDED");question(disabled,"MANUAL","ACTIVE");var r=service.recommend(user,10);Set<String> ids=new HashSet<>(r.items().stream().map(RecommendationDtos.Item::questionId).toList());assertEquals(Set.of(String.valueOf(manual),String.valueOf(ai)),ids);assertEquals(r.items().get(0).reason().priority(),r.items().get(1).reason().priority());}
 @Test void brandNewUserCoversAtMostFiveKnowledgePoints(){for(int i=1;i<=7;i++){long k=kp(i,true);question(k,"MANUAL","ACTIVE");}var r=service.recommend(user,10);assertTrue(r.items().stream().map(RecommendationDtos.Item::knowledgeId).distinct().count()<=5);}
 @Test void versionParametersAndUniqueQuestionIdsAreConsistent(){long k=kp(1,true);for(int i=0;i<3;i++)question(k,"MANUAL","ACTIVE");var r=service.recommend(user,10);assertEquals(cfg.ruleVersion(),r.ruleVersion());r.items().forEach(i->assertEquals(r.ruleVersion(),i.reason().ruleVersion()));assertEquals(cfg.cooldownHours(),r.parameters().cooldownHours());assertEquals(r.items().size(),r.items().stream().map(RecommendationDtos.Item::questionId).distinct().count());}
 @Test void updatingReflectsPendingPracticeSubmittedEvents(){long k=kp(1,true);question(k,"MANUAL","ACTIVE");long activity=db.queryForObject("INSERT INTO rs_learning_activity(user_id,subject_id,kind,status) VALUES (?,1,'PRACTICE','COMPLETED') RETURNING id",Long.class,user);long practice=db.queryForObject("INSERT INTO rs_practice(activity_id,user_id,subject_id,question_count,mix_ratio_json,request_key) VALUES (?,?,1,1,'{}','m06-updating') RETURNING id",Long.class,activity,user);db.update("INSERT INTO rs_change_event(event_type,source_id,source_revision,state) VALUES ('PRACTICE_SUBMITTED',?,1,'PENDING')",practice);assertTrue(service.recommend(user,1).updating());db.update("UPDATE rs_change_event SET state='DONE' WHERE source_id=?",practice);assertFalse(service.recommend(user,1).updating());long taskAct=db.queryForObject("INSERT INTO rs_learning_activity(user_id,subject_id,kind,status) VALUES (?,1,'TASK','COMPLETED') RETURNING id",Long.class,user);long task=db.queryForObject("INSERT INTO rs_review_task(activity_id,user_id,subject_id,status,question_count,mix_ratio_json,rule_version,request_key,request_hash) VALUES (?,?,1,'COMPLETED',1,'{}','v1','m06-task-upd',?) RETURNING id",Long.class,taskAct,user,"0".repeat(64));db.update("INSERT INTO rs_change_event(event_type,source_id,source_revision,state) VALUES ('TASK_SUBMITTED',?,1,'PENDING')",task);assertTrue(service.recommend(user,1).updating());db.update("DELETE FROM rs_change_event WHERE event_type='TASK_SUBMITTED' AND source_id=?",task);db.update("DELETE FROM rs_review_task WHERE id=?",task);}
 @Test void diagnosticPoolLargerThanSlotsDoesNotOvershootCount(){long review=kp(1,true);for(int i=0;i<8;i++)question(review,"MANUAL","ACTIVE");snapshot(review,3,"60",NOW.minus(1,ChronoUnit.DAYS));for(int x=2;x<=8;x++){long k=kp(x,true);question(k,"MANUAL","ACTIVE");}var r=service.recommend(user,10);assertEquals(10,r.items().size());assertEquals(8,r.review().size());assertEquals(2,r.diagnostic().size());assertTrue(r.shortfall().isEmpty());assertEquals(r.items().stream().map(RecommendationDtos.Item::knowledgeId).distinct().count(),r.plannedKnowledge().size());}

 long kp(int order,boolean enabled){long id=db.queryForObject("INSERT INTO rs_knowledge_point(subject_id,chapter_id,code,name,sort_order,enabled) VALUES (1,?,?,?,?,?) RETURNING id",Long.class,chapter,prefix+"K"+order,prefix+"K"+order,order,enabled);kps.add(id);return id;}
 long question(long kp,String origin,String status){String no=(prefix+"Q"+questions.size()).substring(0,Math.min(24,(prefix+"Q"+questions.size()).length()));long q=db.queryForObject("INSERT INTO rs_question(subject_id,question_no,origin,status) VALUES (1,?,?,?) RETURNING id",Long.class,no,origin,status);long v=db.queryForObject("INSERT INTO rs_question_version(question_id,version,subject_id,knowledge_point_id,type,max_score,content_json,answer_json) VALUES (?,1,1,?,'CHOICE',2,'{\"stem\":\"s\",\"options\":[]}'::jsonb,'{\"correctOption\":\"A\"}'::jsonb) RETURNING id",Long.class,q,kp);db.update("UPDATE rs_question SET current_version_id=? WHERE id=?",v,q);questions.add(q);return q;}
 long version(long q){return db.queryForObject("SELECT current_version_id FROM rs_question WHERE id=?",Long.class,q);}
 long evidence(long kp,long q,String y,String type,Instant at){return db.queryForObject("INSERT INTO rs_evidence(user_id,source_type,submission_id,question_id,question_version_id,knowledge_id,question_type,result_y,weight,source_revision,submitted_at,graded_at) VALUES (?,'PRACTICE',?,?,?,?,?,?,1,1,?,?) RETURNING id",Long.class,user,100000+questions.indexOf(q),q,version(q),kp,type,y==null?null:new BigDecimal(y),OffsetDateTime.ofInstant(at,ZoneOffset.UTC),OffsetDateTime.ofInstant(at,ZoneOffset.UTC));}
 void snapshot(long kp,int n,String score,Instant latest){long id=db.queryForObject("INSERT INTO rs_mastery_snapshot(user_id,knowledge_id,n,weight_sum,weighted_sum,rule_score,final_score,clamped,status,ai_reason_json,evidence_revision,rule_version,evidence_ids_json,latest_practice_at,cutoff_at) VALUES (?,?,?,1,1,?,?,false,'CONSOLIDATE','{}',1,'mastery-v1','[]',?,?) RETURNING id",Long.class,user,kp,n,new BigDecimal(score),new BigDecimal(score),OffsetDateTime.ofInstant(latest,ZoneOffset.UTC),OffsetDateTime.ofInstant(NOW,ZoneOffset.UTC));db.update("INSERT INTO rs_mastery_current(user_id,knowledge_id,snapshot_id,evidence_revision) VALUES (?,?,?,1)",user,kp,id);}
 static void same(String expected,BigDecimal actual){assertEquals(0,new BigDecimal(expected).compareTo(actual),()->expected+" != "+actual);}
}
